-- Editorial Vietnamese sample. Idempotent: preserve an existing guide and its images.
USE fashion_ai;
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO style_guides(style_id,language_id,content,content_version)
SELECT s.id,l.id,'{"overview":{"definition":"Old Money trong cẩm nang này là một cách diễn giải thẩm mỹ: trang phục cổ điển, độ vừa vặn được chăm chút và phụ kiện tiết chế. Đây không phải tiêu chuẩn về thu nhập, xuất thân hay cách người giàu thực sự ăn mặc.","origin":"Không có một ngày ra đời duy nhất cho nhãn Old Money hiện nay. Vogue mô tả nó có quan hệ với cách gọi preppy trước đây; triển lãm Ivy Style của Museum at FIT giúp tìm hiểu một phần nền tảng trang phục học đường mà thẩm mỹ này thường tham khảo.","spirit":"Ưu tiên sự chỉn chu và tính sử dụng lâu dài. Hãy chọn phom, màu và chất liệu hợp nhu cầu của mình thay vì cố chứng minh địa vị qua thương hiệu. Áo được sửa vừa người thường hữu ích hơn một món đắt nhưng không thoải mái.","context":"Ở đây, Old Money là nhãn phong cách đương đại lấy cảm hứng từ một số hình ảnh cổ điển, không phải bản mô tả chính xác toàn bộ lịch sử hay một tầng lớp xã hội. Cách áp dụng dưới đây là gợi ý biên soạn cho đời sống hiện tại, đặc biệt có điều chỉnh với khí hậu nóng."},"recognition":[{"title":"Phom dáng","detail":"Vai áo vừa điểm vai, thân áo có khoảng cử động; quần thẳng hoặc suông nhẹ, chân váy chữ A hoặc dáng cột đều có thể dùng. Không cần ôm sát: thử ngồi, bước lên cầu thang và giơ tay trước khi chọn."},{"title":"Đường cắt","detail":"Blazer một hàng khuy, cổ ve vừa và đường ly quần tạo nét rõ ràng. Đường gấu phẳng, khuy chắc và đường may không bị kéo quan trọng hơn việc chọn một nhãn hàng cụ thể."},{"title":"Họa tiết","detail":"Màu trơn dễ làm nền; sọc nhỏ, kẻ ô nhẹ hoặc dệt nổi có thể tạo nhịp. Nếu dùng một họa tiết rõ, thử giữ các món còn lại đơn giản để thấy được chất liệu và đường cắt."},{"title":"Chất liệu và thời tiết","detail":"Cotton, linen pha hoặc vải dệt có bề mặt lì phù hợp ngày nóng; len mỏng thích hợp phòng điều hòa. Linen nhăn là đặc tính tự nhiên, không phải lỗi. Kiểm tra độ xuyên thấu và cảm giác trên da thay vì mặc định sợi tự nhiên luôn tốt hơn sợi pha."}],"palette":[{"name":"Trắng ngà","hex":"#F5F0E8","combination":"Dùng cho áo hoặc quần sáng; phối xanh navy tạo độ tương phản nhẹ."},{"name":"Be cát","hex":"#D6C3A5","combination":"Làm nền cho quần hoặc blazer; phối trắng ngà và nâu chocolate."},{"name":"Xanh navy","hex":"#24334A","combination":"Dùng cho blazer hoặc váy; hợp áo trắng, be hoặc xanh nhạt."},{"name":"Nâu chocolate","hex":"#5A4033","combination":"Lặp ở thắt lưng và giày để liên kết bộ đồ; không cần khớp tuyệt đối từng sắc."},{"name":"Xám đá","hex":"#A6A5A0","combination":"Thử phối với navy hoặc trắng ngà cho bộ đồ công sở."},{"name":"Xanh sơ mi","hex":"#B8CAD8","combination":"Một màu sáng dịu cho sơ mi; phối quần be hoặc navy."}],"garments":[{"title":"Sơ mi","detail":"Sơ mi cotton hoặc linen pha là điểm tựa cho nhiều bộ đồ. Chọn cổ giữ dáng vừa đủ, thân không căng ở cúc; sơ vin toàn bộ, một phần hoặc để ngoài tùy tỷ lệ và sở thích."},{"title":"Blazer","detail":"Blazer navy hoặc be tạo cấu trúc cho trang phục cơ bản. Kiểu không lót hoặc lót nhẹ hữu ích với thời tiết nóng; thử vai vừa và phần tay không cản cử động."},{"title":"Quần âu","detail":"Quần thẳng, suông hoặc có ly giúp tạo đường dọc. Chọn cạp dễ chịu và chiều dài phù hợp đôi giày thường đi; chỉnh gấu thay vì buộc phải dùng giày cao gót."},{"title":"Cardigan hoặc áo len mỏng","detail":"Thêm một lớp mềm khi đi học hoặc ngồi phòng điều hòa. Dệt mỏng giúp giảm độ cồng kềnh; có thể khoác vai nếu tiện, không phải bước bắt buộc."},{"title":"Chân váy midi","detail":"Dáng chữ A hoặc cột là lựa chọn thay cho quần. Độ dài nên được thử cùng giày và khi đi lại; chọn đường xẻ hoặc vải đủ co giãn nếu cần bước dài."},{"title":"Polo và áo cổ tròn","detail":"Giảm mức trang trọng cho ngày nghỉ. Bề mặt gọn, cổ không bị cuộn và độ dài hợp quần là những chi tiết dễ chăm chút."}],"accessories":[{"title":"Giày","detail":"Loafer, ballet flat hoặc giày gót thấp giúp bộ đồ gọn. Với ngày đi bộ nhiều, sneaker đơn giản là lựa chọn thực tế; độ êm và khả năng bám sàn quan trọng hơn một hình dáng cố định."},{"title":"Túi","detail":"Túi có cấu trúc vừa, đủ chứa vật dụng thật sự mang theo. Túi tote canvas gọn có thể hợp đi học; túi da hoặc chất liệu thay thế bề mặt lì hợp bộ đồ công sở."},{"title":"Trang sức","detail":"Thử đồng hồ, khuyên nhỏ hoặc một dây chuyền mảnh. Ngọc trai là một lựa chọn, không phải điều kiện để mặc Old Money; có thể bỏ trang sức nếu công việc hoặc da nhạy cảm không phù hợp."},{"title":"Thắt lưng và khăn","detail":"Thắt lưng giúp kết nối quần và giày; khăn nhỏ có thể thêm màu ở cổ hoặc quai túi. Tránh siết quá chặt chỉ để tạo eo hoặc đeo khăn nếu thấy nóng."},{"title":"Phụ kiện tóc","detail":"Kẹp nhỏ, dây buộc tóc trơn hoặc băng đô đơn giản giữ tóc tiện hoạt động. Mái tóc tự nhiên hoặc tóc xoăn đều phù hợp; không có một kiểu tóc bắt buộc."}],"outfits":[{"key":"linen-campus","name":"Linen gọn cho ngày học","items":["Sơ mi linen pha trắng ngà","Quần suông navy","Sneaker sáng màu hoặc loafer êm","Tote canvas gọn"],"explanation":"Áo thoáng kết hợp quần có đường dọc tạo nét chỉn chu mà vẫn thuận tiện ngồi học và di chuyển. Sơ vin một phần nếu thấy dễ chịu; chọn sneaker khi phải đi bộ nhiều.","occasions":["Đi học","Đi chơi ban ngày"],"imageUrl":null},{"key":"navy-work","name":"Navy cho buổi làm việc","items":["Blazer navy lót nhẹ","Sơ mi xanh nhạt","Quần âu be","Loafer nâu","Túi có cấu trúc"],"explanation":"Blazer tạo đường vai rõ, sơ mi xanh nhạt làm dịu navy và quần be tạo khoảng sáng. Lặp sắc nâu ở giày hoặc thắt lưng để liên kết; tháo blazer khi ra ngoài trời nóng.","occasions":["Đi làm","Gặp khách hàng"],"imageUrl":null},{"key":"weekend-polo","name":"Cuối tuần với polo","items":["Polo màu kem","Quần thẳng nâu nhạt","Ballet flat hoặc sneaker","Túi đeo chéo nhỏ"],"explanation":"Polo giữ một chút nét cổ điển nhưng bớt trang trọng hơn sơ mi. Quần thẳng cân bằng thân áo; túi nhỏ giữ tổng thể nhẹ và đủ tiện cho đi cà phê.","occasions":["Đi chơi","Cà phê"],"imageUrl":null},{"key":"midi-museum","name":"Midi cho buổi xem triển lãm","items":["Áo dệt kim mỏng cổ tròn","Chân váy midi chữ A navy","Giày bệt mềm","Khuyên nhỏ","Túi vừa"],"explanation":"Bề mặt dệt kim tạo chiều sâu bên cạnh váy trơn. Váy chữ A và giày bệt phù hợp đứng lâu; thử gấu không mắc vào giày trước khi đi.","occasions":["Đi chơi","Xem triển lãm"],"imageUrl":null},{"key":"dinner-ivory","name":"Bữa tối sắc ngà","items":["Áo blouse trắng ngà không xuyên thấu","Quần âu xám đá hoặc chân váy cột","Giày gót thấp","Túi nhỏ","Một món trang sức điểm nhấn"],"explanation":"Áo có độ rủ mềm giúp bộ đồ bớt giống đồng phục công sở. Một điểm sáng ở phụ kiện đủ tạo cảm giác có chủ đích; giày gót thấp là lựa chọn thoải mái.","occasions":["Bữa tối","Tiệc nhẹ"],"imageUrl":null},{"key":"cardigan-office","name":"Cardigan trong phòng điều hòa","items":["Áo cổ tròn sáng màu","Cardigan navy mỏng","Quần suông be","Loafer êm","Đồng hồ đơn giản"],"explanation":"Hai lớp mỏng dễ điều chỉnh nhiệt độ hơn một áo dày. Giữ áo trong gọn để cardigan không phồng; màu navy và be tạo nền linh hoạt cho trang sức hoặc túi sẵn có.","occasions":["Đi làm","Đi học"],"imageUrl":null}],"occasions":[{"title":"Đi học","detail":"Ưu tiên vải thoáng, giày êm và túi đủ sách; giảm các lớp áo nếu lớp học không có điều hòa. Kiểm tra quy định đồng phục trước, không cần mặc blazer để đạt phong cách."},{"title":"Đi làm","detail":"Điều chỉnh độ trang trọng theo môi trường. Sơ mi và quần âu có thể đủ ở nơi linh hoạt; thêm blazer khi cần. Công việc vận động nhiều nên chọn phom và giày bảo đảm an toàn."},{"title":"Đi chơi","detail":"Polo, sơ mi thoáng hoặc cardigan mỏng dễ phối với quần và váy sẵn có. Chọn túi nhỏ hơn và tránh phụ kiện gây vướng nếu lịch trình có nhiều hoạt động."},{"title":"Dự tiệc","detail":"Phù hợp bữa tối hoặc tiệc có dress code thanh lịch; có thể thêm chất liệu rủ và phụ kiện điểm nhấn. Không thay thế yêu cầu trang phục black tie hoặc nghi lễ cụ thể: đọc dress code của sự kiện trước."}],"suitability":[{"title":"Sở thích và nhu cầu","detail":"Hợp người thích trang phục chỉn chu, dễ phối lại và ít chi tiết nổi bật. Nếu thích màu rực hoặc họa tiết lớn, có thể giữ phom cổ điển và thêm một món theo gu riêng."},{"title":"Muốn tạo cảm giác cao hơn","detail":"Có thể thử quần vừa chiều dài, đường ly và sắc màu liên tục; blazer ngắn hơn là một lựa chọn. Không cần bỏ quần rộng, váy midi hoặc giày bệt vì chiều cao."},{"title":"Muốn nhấn eo","detail":"Thử blazer có chiết nhẹ hoặc sơ vin với cạp dễ chịu; thắt lưng chỉ là phụ kiện tùy chọn. Nếu không thích nhấn eo, phom thẳng vẫn diễn đạt được tinh thần chỉn chu."},{"title":"Cần khoảng rộng ở vai, ngực hoặc hông","detail":"Thử phom có đủ cử động, điều chỉnh cúc và đường may; quần có ly hoặc áo ít lót có thể tăng sự thoải mái. Chọn theo số đo thật thay vì cố ép cơ thể vào một cỡ."},{"title":"Cá tính, ngân sách và cơ thể","detail":"Mọi vóc dáng đều có thể mặc. Bắt đầu từ đồ có sẵn, mua đồ cũ còn tốt hoặc sửa phom nếu hợp nhu cầu; không cần mô phỏng địa vị xã hội hay mua thương hiệu cao cấp."}],"mistakes":[{"title":"Mặc định đắt tiền mới đúng","detail":"Khắc phục bằng việc kiểm tra phom, tình trạng vải và tần suất sử dụng trước giá hay logo. Một món được chăm sóc tốt có thể phục vụ mục tiêu chỉn chu."},{"title":"Áo quá chật hoặc quá cứng","detail":"Cúc bị kéo, vai bó và cánh tay khó nâng làm giảm tiện dụng. Thử cỡ hoặc phom khác, ưu tiên cử động; sửa gấu hoặc tay khi cần."},{"title":"Phối quá nhiều dấu hiệu cổ điển cùng lúc","detail":"Blazer, khăn, ngọc trai và mũ đều có thể dùng, nhưng không cần xuất hiện cùng lúc. Chọn một điểm nhấn rồi cân bằng với đồ nền nếu muốn tổng thể nhẹ hơn."},{"title":"Mặc nhiều lớp bất chấp thời tiết","detail":"Dùng sơ mi nhẹ, blazer ít lót hoặc cardigan mỏng; bỏ lớp khoác khi nóng. Thoải mái và phù hợp hoàn cảnh là mục tiêu, không phải giữ nguyên một hình ảnh tham khảo."},{"title":"Giữ quy tắc màu và phụ kiện quá cứng","detail":"Giày và túi không nhất thiết giống hệt màu; trung tính cũng không phải lựa chọn duy nhất. Thử một màu mình thích rồi quan sát độ tương phản và tỷ lệ."}],"gettingStarted":{"essentials":[{"title":"Một sơ mi sáng màu","detail":"Chọn cotton hoặc linen pha với độ kín và độ thoáng hợp nhu cầu; có thể dùng chiếc đã có."},{"title":"Một quần thẳng hoặc suông","detail":"Navy, be hoặc xám dễ phối; cạp và gấu nên thuận tiện cho đôi giày thường dùng."},{"title":"Một cardigan mỏng hoặc blazer nhẹ","detail":"Chọn theo khí hậu và công việc, không cần mua cả hai ngay."},{"title":"Một đôi giày đi được lâu","detail":"Loafer, ballet flat hoặc sneaker đơn giản đều có thể dùng nếu hợp hoạt động."},{"title":"Một túi hoặc thắt lưng hữu ích","detail":"Ưu tiên chức năng thật; dùng đồ sẵn có nếu còn phù hợp thay vì mua chỉ để đủ bộ."}],"steps":[{"title":"Kiểm kê tủ đồ","detail":"Chọn đồ nền còn tốt và ghi lại món đã có. Tạo một bộ đi học/đi làm từ đó trước khi quyết định mua."},{"title":"Chọn một công thức theo lịch sinh hoạt","detail":"Bắt đầu với sơ mi + quần thẳng + giày êm. Thử đi lại, ngồi và giơ tay; sửa tỷ lệ nếu bất tiện."},{"title":"Giới hạn điểm nhấn theo gu","detail":"Thử hai màu nền và một điểm nhấn nhỏ để dễ quan sát tổng thể; đây là bài tập bắt đầu, không phải quy tắc bắt buộc."},{"title":"Điều chỉnh cho thời tiết","detail":"Mặc thử vào nhiệt độ thực tế, kiểm tra độ xuyên thấu và nhu cầu giặt. Đổi chất liệu hoặc bỏ lớp khoác nếu nóng."},{"title":"Đánh giá sau khi mặc","detail":"Ghi lại độ thoải mái và món đã dùng nhiều. Chỉ bổ sung phần thật sự thiếu; tham khảo ảnh của chính mình thay vì so cơ thể với người mẫu."}]},"sources":[{"title":"The Museum at FIT — Ivy Style","url":"https://sites.fitnyc.edu/depts/museum/Ivy_Style/","supports":"Bối cảnh Ivy/preppy trong phần tổng quan; không dùng để xác lập một ngày ra đời của Old Money."},{"title":"Vogue — The Aesthetics, -Cores, and Microtrends That Defined 2023","url":"https://www.vogue.com/article/core-aesthetic-microtrends-2023","supports":"Cách dùng nhãn Old Money đương đại và mối liên hệ với preppy. Các công thức phối đồ là gợi ý biên soạn riêng của NOVA ATELIER."}]}',1
FROM styles s JOIN languages l ON l.code='vi' WHERE s.code='OLD_MONEY'
ON DUPLICATE KEY UPDATE content=style_guides.content;
COMMIT;
